    n_grove: 'Kristallhain', n_garden: 'Korallengarten', n_vent: 'Warmer Spalt', n_wreck: 'Wrack einer Galeone',
    grove: ['Zwischen den Felsen stehen violette Kristalle, dicht an dicht. Sie leuchten von innen, als hätte jemand Licht in ihnen vergessen.', 'Ein Hain aus Kristallen. Wenn der Scheinwerfer sie trifft, werfen sie das Licht in Farben zurück.'],
    garden: ['Ein Garten aus Korallen, türkis und flieder. Überall Lichtpunkte und kleine Fische, die vor dem Boot ausweichen.', 'Korallen, so weit der Scheinwerfer reicht. Hier ist es heller als anderswo, und es fühlt sich bewohnt an.'],
    vent: ['Ein Spalt im Grund, aus dem es warm und orange leuchtet. Das Wasser flimmert darüber, und Blasen steigen auf.', 'Zwischen dunklen Felsnadeln glüht etwas. Das einzige warme Licht seit Langem, außer meinem eigenen.'],
    wreck: ['Ein Schiff, auf der Seite liegend. Im Heck brennt noch ein Licht, und niemand ist da, der es angezündet haben könnte.'],
    n_plain: 'Die stille Ebene', n_whale: 'Walskelett', n_bell: 'Taucherglocke',
    s_grove: 'Kristallhain', s_grotto: 'Kristallgrotte', s_garden: 'Korallengarten', s_vent: 'Warmer Spalt', s_wreck: 'Schiffswrack', s_plain: 'Schnee-Ebene', s_whale: 'Walskelett', s_bell: 'Taucherglocke', s_hole: 'Das Loch', compass: ['N', 'O', 'S', 'W'],
    plain: ['Der Grund fällt ab, und plötzlich ist alles still. Es schneit. Feine weiße Flocken sinken aus der Dunkelheit, so langsam, als hätte hier unten niemand Eile.'],
    whale: ['Ein Wal, oder was von ihm geblieben ist. Die Rippen wölben sich über mir wie das Gewölbe einer Kirche. An den Knochen wächst etwas, das ganz schwach leuchtet.'],
    bell: ['Eine alte Taucherglocke aus Gusseisen, schief im Sand und voller Rost. Die kleinen Fenster sind blind. Jemand hat sie vor sehr langer Zeit hier herabgelassen und nicht wieder heraufgeholt.'],
    where: 'Etwa {d} m {dir} der Startschlucht.', dirs: ['nördlich', 'nordöstlich', 'östlich', 'südöstlich', 'südlich', 'südwestlich', 'westlich', 'nordwestlich'],
